/** Hero -- generated by the template lab from Figma node 538:38694
 *  (Hero). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- lead, amount, code;
 *    board copy, editable -- climb-gear, camp-hike, summer-apparel, footwear, text, off, cta/shop-all-eligible-items;
 *    photos -- photo, product-cutout/photo, product-cutout/photo-2; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaStroke, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const HERO_538_38694_FIGMA = {
  "climb-gear": "538:38702", // text: Climb Gear
  "camp-hike": "538:38709", // text: Camp & Hike
  "summer-apparel": "538:38716", // text: Summer Apparel
  "footwear": "538:38723", // text: Footwear
  "lead": "538:38730", // lead: EXTRA
  "amount": "538:38731", // amount: 20
  "text": "538:38732", // text: %
  "off": "538:38733", // text: OFF
  "code": "538:38734", // code: CODE CAMPOUT20
  "cta/shop-all-eligible-items": "538:38736", // text: Shop All Eligible Items
  "cat-buttons/cat-2": "538:38699", // pill: CAT 2
  "cat-2/arrow": "538:38703", // graphic: Arrow
  "cat-buttons/cat-1": "538:38706", // pill: CAT 1
  "cat-1/arrow": "538:38710", // graphic: Arrow
  "cat-buttons/cat-8": "538:38713", // pill: CAT 8
  "cat-8/arrow": "538:38717", // graphic: Arrow
  "cat-buttons/cat-4": "538:38720", // pill: CAT 4
  "cat-4/arrow": "538:38724", // graphic: Arrow
  "art/vector-741": "538:38728", // graphic: Vector 741
  "cta/cta": "538:38735", // pill: CTA
  "product-cutout/photo": "538:38708", // photo: image 3726
  "product-cutout/photo-2": "538:38715", // photo: image 3753
} as const;

export function Hero_538_38694({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [HERO_538_38694_FIGMA["climb-gear"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/climb-gear`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["camp-hike"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/camp-hike`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["summer-apparel"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/summer-apparel`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["footwear"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/footwear`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [HERO_538_38694_FIGMA["amount"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/amount`} contract="lab.amount" layout={layout}
      text={l.text!.chars.replace(/\d+/, (asset.copy.offer ?? '').match(/(\d+)\s*%/)?.[1] ?? (asset.copy.offer ?? '').match(/\d+/)?.[0] ?? '$&')} />,
    [HERO_538_38694_FIGMA["text"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/text`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["off"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/off`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["code"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/code`} contract="lab.code" layout={layout}
      text={asset.copy.code ? l.text!.chars.replace(/^(\s*code\s+)\S+/i, `$1${asset.copy.code}`) : l.text!.chars} />,
    [HERO_538_38694_FIGMA["cta/shop-all-eligible-items"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta/shop-all-eligible-items`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [HERO_538_38694_FIGMA["cat-buttons/cat-2"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-2/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_38694_FIGMA["cat-2/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-2/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [HERO_538_38694_FIGMA["cat-buttons/cat-1"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-1/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_38694_FIGMA["cat-1/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-1/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [HERO_538_38694_FIGMA["cat-buttons/cat-8"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-8/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_38694_FIGMA["cat-8/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-8/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [HERO_538_38694_FIGMA["cat-buttons/cat-4"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-4/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_38694_FIGMA["cat-4/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-4/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [HERO_538_38694_FIGMA["art/vector-741"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/art/vector-741/mark`} src="/graphics/named-sale-vector-741-1ia1jwb.svg"
      fill="#F14221" layout={layout} />,
    [HERO_538_38694_FIGMA["cta/cta"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cta/cta/mark`} src="/graphics/named-sale-pill-791x120-1kjwgk5.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [HERO_538_38694_FIGMA["product-cutout/photo"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/product-cutout/photo`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
    [HERO_538_38694_FIGMA["product-cutout/photo-2"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/product-cutout/photo-2`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
